const fn = new Function(code + "\nreturn { buildQuery };");
const { buildQuery } = fn();
const url = buildQuery("/api/items", { q: "web dev", page: 2 });
const parsed = new URL(url, "https://x.dev");
if (parsed.pathname !== "/api/items") throw new Error("The base path must survive.");
if (parsed.searchParams.get("q") !== "web dev") throw new Error("q must round-trip through URLSearchParams.");
if (parsed.searchParams.get("page") !== "2") throw new Error("Numbers must be stringified.");

